// utils/observers/{observer}/{Observer}EventBus.ts
// Observer — bus d'événements typé pour {Observer}

type {Observer}EventCallback<T = unknown> = (data?: T) => void

export class {Observer}EventBus {
  private events: Map<string, Set<{Observer}EventCallback>> = new Map()

  // Souscription — retourne une fonction de désabonnement
  subscribe<T>(event: string, callback: {Observer}EventCallback<T>): () => void {
    if (!this.events.has(event)) {
      this.events.set(event, new Set())
    }
    this.events.get(event)!.add(callback as {Observer}EventCallback)

    // Retourner la fonction de désabonnement — toujours appeler dans onUnmounted
    return () => this.unsubscribe(event, callback as {Observer}EventCallback)
  }

  // Publication — notifie tous les abonnés
  publish<T>(event: string, data?: T): void {
    this.events.get(event)?.forEach(callback => {
      try {
        callback(data)
      } catch (error) {
        console.error(`[{Observer}EventBus] Erreur dans le callback de "${event}":`, error)
      }
    })
  }

  private unsubscribe(event: string, callback: {Observer}EventCallback): void {
    this.events.get(event)?.delete(callback)
    if (this.events.get(event)?.size === 0) {
      this.events.delete(event)
    }
  }

  clear(event?: string): void {
    if (event) this.events.delete(event)
    else       this.events.clear()
  }

  subscriberCount(event: string): number {
    return this.events.get(event)?.size ?? 0
  }
}

// Singleton — une seule instance pour toute l'application
export const {observer}EventBus = new {Observer}EventBus()

// composables/{observer}/use{Observer}Events.ts
import { {observer}EventBus } from '~/utils/observers/{observer}/{Observer}EventBus'

export const use{Observer}Events = () => {
  // Souscription avec désabonnement automatique dans onUnmounted
  const on = <T>(event: string, callback: (data?: T) => void) => {
    const unsubscribe = {observer}EventBus.subscribe<T>(event, callback)
    onUnmounted(unsubscribe)
    return unsubscribe
  }

  const emit = <T>(event: string, data?: T) => {
    {observer}EventBus.publish<T>(event, data)
  }

  return { on, emit }
}

// tests/utils/observers/{observer}/{Observer}EventBus.spec.ts
import { describe, it, expect, vi } from 'vitest'
import { {Observer}EventBus } from '~/utils/observers/{observer}/{Observer}EventBus'

const makebus = () => new {Observer}EventBus()

describe('{Observer}EventBus', () => {

  it('subscribe() + publish() notifie le callback', () => {
    const bus = makebus()
    const cb  = vi.fn()
    bus.subscribe('event', cb)
    bus.publish('event', 'data')
    expect(cb).toHaveBeenCalledWith('data')
  })

  it('plusieurs abonnés reçoivent la notification', () => {
    const bus = makebus()
    const cb1 = vi.fn(), cb2 = vi.fn()
    bus.subscribe('event', cb1)
    bus.subscribe('event', cb2)
    bus.publish('event', 42)
    expect(cb1).toHaveBeenCalledWith(42)
    expect(cb2).toHaveBeenCalledWith(42)
  })

  it('la fonction de désabonnement retire le callback', () => {
    const bus         = makebus()
    const cb          = vi.fn()
    const unsubscribe = bus.subscribe('event', cb)
    unsubscribe()
    bus.publish('event', 'data')
    expect(cb).not.toHaveBeenCalled()
  })

  it('publish() sans abonnés ne lève pas d\'erreur', () => {
    const bus = makebus()
    expect(() => bus.publish('inexistant', 'data')).not.toThrow()
  })

  it('clear() supprime tous les abonnés', () => {
    const bus = makebus()
    const cb  = vi.fn()
    bus.subscribe('event', cb)
    bus.clear()
    bus.publish('event', 'data')
    expect(cb).not.toHaveBeenCalled()
  })

  it('subscriberCount() retourne le bon nombre', () => {
    const bus = makebus()
    const u1  = bus.subscribe('e', vi.fn())
    const u2  = bus.subscribe('e', vi.fn())
    expect(bus.subscriberCount('e')).toBe(2)
    u1()
    expect(bus.subscriberCount('e')).toBe(1)
  })

  it('une erreur dans un callback n\'empêche pas les autres', () => {
    const bus = makebus()
    const cb1 = vi.fn().mockImplementation(() => { throw new Error('oops') })
    const cb2 = vi.fn()
    bus.subscribe('e', cb1)
    bus.subscribe('e', cb2)
    expect(() => bus.publish('e')).not.toThrow()
    expect(cb2).toHaveBeenCalled()
  })

})
